#python-diagnostics { margin-top: 0.35rem; }
#python-diagnostics summary { cursor: pointer; color: var(--danger); }
#python-traceback {
  max-height: 10rem;
  overflow: auto;
  white-space: pre;
  font-size: 0.7rem;
  user-select: text;
}

.preview-pane:fullscreen {
  width: 100%;
  height: 100%;
  border: 0;
}
.preview-pane:fullscreen .canvas-wrap { container-type: size; }
.preview-pane:fullscreen .canvas-frame {
  max-width: none;
  width: min(100cqw, calc(100cqh * 16 / 9));
}

.python-editor-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  padding: 0.35rem 0.55rem;
  border-bottom: 1px solid var(--border);
  flex: none;
  font-size: 0.68rem;
}
.python-editor-tools .secondary-button { padding: 0.3rem 0.45rem; font-size: 0.68rem; }
.python-editor-tool-status { color: var(--muted); overflow-wrap: anywhere; }
.python-editor-help { position: relative; }
.python-editor-help summary { cursor: pointer; }
.python-editor-help[open] > div {
  position: absolute;
  z-index: 10;
  top: 1.5rem;
  right: 0;
  width: min(20rem, 70vw);
  padding: 0.8rem;
  line-height: 1.6;
  background: #171d2a;
  border: 1px solid var(--border);
  border-radius: 0.5rem;
